import{B as e,Q as t,s as n,z as r}from"./chunks/framework.hue4hZNP.js";import"./chunks/league-standings.DJwAobDR.js";var i=JSON.parse(`{"title":"Report Match Results","description":"","frontmatter":{},"headers":[],"relativePath":"guide/report-match-results.md","filePath":"guide/report-match-results.md"}`),a={name:`guide/report-match-results.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="report-match-results" tabindex="-1">Report Match Results <a class="header-anchor" href="#report-match-results" aria-label="Permalink to &quot;Report Match Results&quot;">​</a></h1><p>A player&#39;s guide to reporting the results of matches booked for your wrestler — the heartbeat of league play. When a league match featuring your wrestler is booked, you get an inbox notification asking you to report who won.</p><p><strong>Who this is for:</strong> players with a <a href="./set-player-controlled-wrestler.html">player-controlled wrestler</a> whose match is up. Booker-run shows don&#39;t need this — the show adjudication decides those.</p><hr><h2 id="step-1-—-find-the-match-report-request" tabindex="-1">Step 1 — Find the match report request <a class="header-anchor" href="#step-1-—-find-the-match-report-request" aria-label="Permalink to &quot;Step 1 — Find the match report request&quot;">​</a></h2><p>Open your <strong>Inbox</strong> from the navigation. Booked matches land as notification items with a <strong>Report Result</strong> button. Each item names the match and your opponent.</p><p><img src="/screenshots/league-match-report.png" alt="Match reporting"></p><hr><h2 id="step-2-—-report-the-winner" tabindex="-1">Step 2 — Report the winner <a class="header-anchor" href="#step-2-—-report-the-winner" aria-label="Permalink to &quot;Step 2 — Report the winner&quot;">​</a></h2><p>Click <strong>Report Result</strong>. The report dialog shows the match&#39;s participants:</p><ol><li>Pick the <strong>Winner</strong> from the participants list.</li><li>Click <strong>Submit</strong>.</li></ol><p>That&#39;s it — the result flows into league standings immediately: wins, losses, and draws update on the league dashboard, and your opponent sees the outcome too.</p><blockquote><p>💡 <strong>Report promptly.</strong> League play stalls while matches await results — the standings can&#39;t settle until every booked match has a winner. If you can&#39;t play, coordinate with your commissioner.</p></blockquote><hr><h2 id="step-3-—-watch-the-standings" tabindex="-1">Step 3 — Watch the standings <a class="header-anchor" href="#step-3-—-watch-the-standings" aria-label="Permalink to &quot;Step 3 — Watch the standings&quot;">​</a></h2><p>On the <strong>League</strong> page, the dashboard shows current standings (wins, losses, draws per wrestler) and complete rosters for all players. Your reported results update these live.</p><p><img src="/screenshots/league-standings.png" alt="League standings"></p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>No Report Result button on an inbox item</strong> — the item isn&#39;t a match-fulfillment notification, or the match was already reported. Only matches awaiting a result show the button.</li><li><strong>Dialog won&#39;t submit</strong> — a winner must be selected; the dialog won&#39;t accept an empty pick.</li><li><strong>Wrong wrestler asked to report</strong> — the request goes to the account controlling each participant. See <a href="./set-player-controlled-wrestler.html">Set a Player-Controlled Wrestler</a> if the wrong account holds the link.</li></ul><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./leagues.html">Leagues</a> — creating leagues, the draft, and match booking.</li><li><a href="./set-player-controlled-wrestler.html">Set a Player-Controlled Wrestler</a> — the admin side of handing wrestlers to players.</li><li><a href="./player-dashboard.html">Player Dashboard</a> — your wrestler&#39;s stats and history.</li></ul>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};